INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l49','be tired of','',NULL,'/bi taɪrd ʌv/','He was tired of sleeping on the floor.','他厌倦了睡地板。','I''m tired of waiting.','我等烦了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l49','not ... until','',NULL,'/nɑːt ... ənˈtɪl/','He did not wake up until the bed struck the ground.','直到床落地他才醒。','I won''t go until you come.','你不来我就不走。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l49','save up','',NULL,'/seɪv ʌp/','He saved up for years to buy a bed.','他攒了好几年钱买床。','She is saving up for a trip.','她在攒钱旅行。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l49','send sth crashing','',NULL,'/send ... ˈkræʃɪŋ/','The wind sent the bed crashing into the courtyard.','风把床刮得摔进院子。','He sent the vase crashing to the floor.','他把花瓶碰得摔到地上。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp1','choice','{"stem":"\"___ the weather was very hot, he carried the bed onto the roof.\"(原因:因为)","options":["Although","Because","Until","When"],"answer_index":1,"stem_cn":"因为天很热,他把床搬到了屋顶。","explanation_cn":"表原因用 because(因为)。✓ Because the weather was hot 因为天热。✗ Although:是\"虽然\";✗ When:是\"当…时\";✗ Until:是\"直到\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp1','choice','{"stem":"\"He slept on the roof ___ his room was too hot.\"(原因:因为)","options":["because","until","although","before"],"answer_index":0,"stem_cn":"他睡在屋顶,因为房间太热。","explanation_cn":"表原因用 because。✓ because his room was too hot 因为房间太热。✗ although:虽然;✗ until:直到;✗ before:在…之前。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp1','choice','{"stem":"\"___ he was tired of the floor, he saved up for a bed.\"(原因:因为)","options":["After","Because","Until","Although"],"answer_index":1,"stem_cn":"因为厌倦了睡地板,他攒钱买床。","explanation_cn":"表原因用 because。✓ Because he was tired of the floor 因为厌倦了地板。✗ Although:虽然;✗ Until:直到;✗ After:在…之后。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp2','choice','{"stem":"\"___ he woke up, he was still on the mattress.\"(时间:当…时)","options":["Until","Although","Because","When"],"answer_index":3,"stem_cn":"当他醒来时,还在床垫上。","explanation_cn":"表\"当…时\"用 when。✓ When he woke up 当他醒来时。✗ Because:因为;✗ Although:虽然;✗ Until:直到。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp2','choice','{"stem":"\"He was fast asleep ___ the storm blew up.\"(时间:当…时)","options":["when","unless","because","although"],"answer_index":0,"stem_cn":"暴风雨刮起时他正熟睡着。","explanation_cn":"表\"当…时\"用 when。✓ when the storm blew up 暴风雨刮起时。✗ because:因为;✗ although:虽然;✗ unless:除非。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp3','choice','{"stem":"\"___ the bed was smashed to pieces, the man was unhurt.\"(让步:虽然)","options":["When","Because","Until","Although"],"answer_index":3,"stem_cn":"虽然床摔碎了,那人却没受伤。","explanation_cn":"表让步\"虽然\"用 although。✓ Although the bed was smashed 虽然床摔碎了。✗ Because:因为;✗ When:当…时;✗ Until:直到。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp3','choice','{"stem":"\"___ it was very late, he went to sleep again.\"(让步:虽然)","options":["Until","So","Although","Because"],"answer_index":2,"stem_cn":"虽然很晚了,他又睡着了。","explanation_cn":"表让步\"虽然\"用 although。✓ Although it was very late 虽然很晚了。✗ Because:因为;✗ Until:直到;✗ So:所以(不引导让步)。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp3','choice','{"stem":"\"The man was unhurt ___ the bed was completely destroyed.\"(让步:尽管)","options":["because","although","until","so"],"answer_index":1,"stem_cn":"尽管床彻底毁了,那人却没受伤。","explanation_cn":"表让步\"尽管\"用 although。✓ although the bed was destroyed 尽管床毁了。✗ because:因为;✗ until:直到;✗ so:所以。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp4','choice','{"stem":"\"He did not wake up ___ the bed had struck the ground.\"(直到…才)","options":["until","although","when","because"],"answer_index":0,"stem_cn":"直到床落地他才醒。","explanation_cn":"\"直到…才…\"用 not…until。✓ did not wake up until… 直到…才醒。✗ when:当…时;✗ because:因为;✗ although:虽然。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp4','choice','{"stem":"\"The man did ___ wake up until the bed hit the ground.\"(直到…才…,前半句用否定词)","options":["seldom","not","hardly","never"],"answer_index":1,"stem_cn":"直到床落地那人才醒。","explanation_cn":"\"直到…才…\"结构前半句要用否定词 not。✓ did not wake up until… 直到…才醒。✗ never / hardly / seldom:不与 until 构成\"直到才\"的固定结构。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp4','choice','{"stem":"\"I will not leave ___ you come back.\"(直到…才)","options":["until","when","because","although"],"answer_index":0,"stem_cn":"你不回来我就不走。","explanation_cn":"\"直到…才…\"用 not…until。✓ will not leave until you come back 你不回来我就不走。✗ when:当…时;✗ because:因为;✗ although:虽然。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp5','choice','{"stem":"\"___ he had put the mattress on the floor, he went to sleep.\"(在…之后)","options":["Until","Because","Although","After"],"answer_index":3,"stem_cn":"把床垫放到地上之后,他睡着了。","explanation_cn":"表\"在…之后\"用 after。✓ After he had put it on the floor 把它放到地上之后。✗ Because:因为;✗ Although:虽然;✗ Until:直到。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp5','choice','{"stem":"\"He carried the mattress inside ___ the storm had passed.\"(在…之后)","options":["unless","although","after","because"],"answer_index":2,"stem_cn":"暴风雨过后他把床垫搬进屋。","explanation_cn":"表\"在…之后\"用 after。✓ after the storm had passed 暴风雨过后。✗ because:因为;✗ although:虽然;✗ unless:除非。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp6','choice','{"stem":"\"The young man was tired ___ sleeping on the floor.\"(对…感到厌倦的固定搭配)","options":["at","for","with","of"],"answer_index":3,"stem_cn":"这年轻人厌倦了睡地板。","explanation_cn":"\"对…感到厌倦\"用 be tired of。✓ tired of sleeping on the floor 厌倦睡地板。✗ with / at / for:不与 tired 搭配这个意思。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp6','choice','{"stem":"\"She is tired ___ waiting for the bus.\"(对…感到厌倦的固定搭配)","options":["of","at","with","for"],"answer_index":0,"stem_cn":"她等公交等烦了。","explanation_cn":"\"对…感到厌倦\"用 be tired of。✓ tired of waiting 等烦了。✗ with / at / for:不与 tired 搭配这个意思。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp7','choice','{"stem":"\"He ___ for years to buy a real bed.\"(攒钱、积攒)","options":["saved out","saved in","saved off","saved up"],"answer_index":3,"stem_cn":"他攒了好几年钱买张真正的床。","explanation_cn":"\"攒钱、积攒\"用 save up。✓ saved up for years 攒了多年钱。✗ saved out / saved off / saved in:不是固定搭配。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp7','choice','{"stem":"\"On the third night, a storm ___.\"(暴风雨刮起、加剧)","options":["blew up","blew out","blew in","blew off"],"answer_index":0,"stem_cn":"第三天夜里刮起了暴风雨。","explanation_cn":"\"(暴风雨)刮起、加剧\"用 blow up。✓ a storm blew up 刮起暴风雨。✗ blew out:吹灭;✗ blew off:吹掉;✗ blew in:吹进来。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',5,'am2_l49_gp8','choice','{"stem":"\"The wind swept the bed off the roof and sent it ___ into the courtyard.\"(使某物一路…下去,后接 -ing)","options":["crashed","crashing","crash","to crash"],"answer_index":1,"stem_cn":"风把床从屋顶刮下,使它摔进院子。","explanation_cn":"send sth doing 表\"使某物一路…下去\",后接现在分词。✓ sent it crashing into the courtyard 使它摔进院子。✗ to crash / crash / crashed:此处用 -ing 分词。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',6,NULL,'choice','{"stem":"美语里\"(房子的)院子\"常说:","options":["garden","yard","courtyard","court"],"answer_index":1,"explanation_cn":"美语\"(房子的)院子\"常说 yard;英式说 garden。✓ play in the yard 在院子里玩。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',6,NULL,'choice','{"stem":"美语里\"一楼(地面层)\"常说:","options":["base floor","ground floor","floor one","first floor"],"answer_index":3,"explanation_cn":"美语 first floor 指地面那一层;英式 ground floor 才是地面层(英式 first floor=二楼)。✓ the first floor 一楼。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',6,NULL,'choice','{"stem":"tired 的意思是:","options":["厌倦的;疲倦的","兴奋的","害怕的","饥饿的"],"answer_index":0,"explanation_cn":"tired = 厌倦的;疲倦的。✓ tired of sleeping on the floor 厌倦睡地板。\n顺带记:兴奋的 = excited;饥饿的 = hungry;害怕的 = afraid."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',6,NULL,'choice','{"stem":"smash 的意思是:","options":["搬运","碰碎,摔碎","购买","修理"],"answer_index":1,"explanation_cn":"smash = 碰碎、摔碎。✓ the bed was smashed to pieces 床摔得粉碎。\n顺带记:修理 = mend;搬运 = carry;购买 = buy."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',6,NULL,'choice','{"stem":"glance 的意思是:","options":["眨眼","闭眼","凝视","扫视,一瞥"],"answer_index":3,"explanation_cn":"glance = 扫视、一瞥。✓ glancing at the bits of wood 扫视着木片。\n顺带记:凝视 = stare;闭眼 = close one''s eyes;眨眼 = blink."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',6,NULL,'choice','{"stem":"promptly 的意思是:","options":["迅速地,立即","偶尔地","小心地","缓慢地"],"answer_index":0,"explanation_cn":"promptly = 迅速地、立即。✓ promptly went to sleep 立刻睡着。\n顺带记:缓慢地 = slowly;偶尔地 = occasionally;小心地 = carefully."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',7,NULL,'cloze','{"stem":"第 1 空","context":"A young man saved up for years ___1___ he was tired of sleeping on the floor. ___2___ the weather was hot, he carried the bed onto the roof. ___3___ a storm smashed the bed, he was miraculously unhurt. He did not wake up ___4___ the bed hit the ground.","blank_no":1,"options":["because","although","until","when"],"answer_index":0,"explanation_cn":"表原因用 because。✓ because he was tired of the floor 因为厌倦地板。\n✗ although:虽然;✗ until:直到;✗ when:当…时。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',7,NULL,'cloze','{"stem":"第 2 空","context":"A young man saved up for years ___1___ he was tired of sleeping on the floor. ___2___ the weather was hot, he carried the bed onto the roof. ___3___ a storm smashed the bed, he was miraculously unhurt. He did not wake up ___4___ the bed hit the ground.","blank_no":2,"options":["Because","Although","Until","After"],"answer_index":0,"explanation_cn":"表原因用 because。✓ Because the weather was hot 因为天热。\n✗ Although:虽然;✗ Until:直到;✗ After:在…之后。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',7,NULL,'cloze','{"stem":"第 3 空","context":"A young man saved up for years ___1___ he was tired of sleeping on the floor. ___2___ the weather was hot, he carried the bed onto the roof. ___3___ a storm smashed the bed, he was miraculously unhurt. He did not wake up ___4___ the bed hit the ground.","blank_no":3,"options":["Although","Because","Until","When"],"answer_index":0,"explanation_cn":"表让步\"虽然\"用 although。✓ Although a storm smashed the bed 虽然风暴摔碎了床。\n✗ Because:因为;✗ Until:直到;✗ When:当…时。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',7,NULL,'cloze','{"stem":"第 4 空","context":"A young man saved up for years ___1___ he was tired of sleeping on the floor. ___2___ the weather was hot, he carried the bed onto the roof. ___3___ a storm smashed the bed, he was miraculously unhurt. He did not wake up ___4___ the bed hit the ground.","blank_no":4,"options":["until","when","because","although"],"answer_index":0,"explanation_cn":"\"直到…才…\"用 not…until。✓ did not wake up until the bed hit the ground 直到床落地才醒。\n✗ when:当…时;✗ because:因为;✗ although:虽然。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',8,NULL,'choice','{"stem":"Why did the young man buy a real bed?","options":["He was tired of sleeping on the floor","He wanted to sell it","His old bed broke","It was a gift"],"answer_index":0,"explanation_cn":"课文说 Tired of sleeping on the floor… he saved up… to buy a real bed,他厌倦睡地板才买床。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',8,NULL,'choice','{"stem":"Why did he carry the bed onto the roof?","options":["There was no room inside","Because the weather was very hot","To dry it in the sun","To hide it from thieves"],"answer_index":1,"explanation_cn":"课文说 Because the weather was very hot, he carried the bed onto the roof。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',8,NULL,'choice','{"stem":"What happened on the third night?","options":["He slept peacefully","The bed broke by itself","A storm swept the bed off the roof","He moved back inside"],"answer_index":2,"explanation_cn":"课文说 on the third night, a storm blew up… swept the bed off the roof,第三晚风暴把床刮下屋顶。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',9,NULL,'choice','{"stem":"你想说\"因为天很热,他把床搬到屋顶\"(原因用 because):","options":["When the weather was hot, he carried the bed onto the roof.","Because the weather was hot, he carried the bed onto the roof.","Although the weather was hot, he carried the bed onto the roof.","Until the weather was hot, he carried the bed onto the roof."],"answer_index":1,"explanation_cn":"表原因用 because 引导从句。✓ Because the weather was hot, he carried the bed onto the roof. 场合:说明做某事的原因。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',9,NULL,'choice','{"stem":"你想说\"虽然床摔碎了,他却没受伤\"(让步用 although,不配 but):","options":["Because the bed was smashed, he was unhurt.","Until the bed was smashed, he was unhurt.","Although the bed was smashed, he was unhurt.","Although the bed was smashed, but he was unhurt."],"answer_index":2,"explanation_cn":"让步用 although,且不能再和 but 连用。✓ Although the bed was smashed, he was unhurt. 场合:说\"虽然…但是…\"时,只用一个连词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',9,NULL,'choice','{"stem":"你想说\"直到床落地他才醒\"(直到…才用 not...until):","options":["He did wake up until the bed hit the ground.","He did not wake up when the bed hit the ground.","He woke up until the bed hit the ground.","He did not wake up until the bed hit the ground."],"answer_index":3,"explanation_cn":"\"直到…才…\"用 not…until(前半句否定)。✓ He did not wake up until the bed hit the ground. 场合:说某事直到某时刻才发生。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"smash 的意思是:","options":["购买","搬运","修理","碰碎,摔碎"],"answer_index":3,"explanation_cn":"smash = 碰碎、摔碎。✓ smashed to pieces 摔得粉碎。\n顺带记:修理 = mend;搬运 = carry;购买 = buy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"promptly 的意思是:","options":["迅速地,立即","偶尔地","勉强地","缓慢地"],"answer_index":0,"explanation_cn":"promptly = 迅速地、立即。✓ promptly went to sleep 立刻睡着。\n顺带记:缓慢地 = slowly;偶尔地 = occasionally;勉强地 = reluctantly."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"\"___ the bed was smashed, the man was unhurt.\"(让步:虽然)","options":["When","Until","Because","Although"],"answer_index":3,"stem_cn":"虽然床摔碎了,那人却没受伤。","explanation_cn":"表让步\"虽然\"用 although。✓ Although the bed was smashed 虽然床摔碎了。\n✗ Because:因为;✗ When:当…时;✗ Until:直到。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"\"He did not wake up ___ the bed had struck the ground.\"(直到…才)","options":["because","when","until","although"],"answer_index":2,"stem_cn":"直到床落地他才醒。","explanation_cn":"\"直到…才…\"用 not…until。✓ did not wake up until the bed had struck the ground 直到床落地才醒。\n✗ when:当…时;✗ because:因为;✗ although:虽然。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"\"The man was miraculously unhurt.\" 这句话的意思是:","options":["那人奇迹般地没有受伤。","那人受了重伤。","那人不见了。","那人吓坏了。"],"answer_index":0,"explanation_cn":"The man was miraculously unhurt. miraculously = 奇迹般地,unhurt = 没受伤,意思是\"那人奇迹般地没有受伤\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"\"Tired of sleeping on the floor, he saved up for a real bed.\" 这句话的意思是:","options":["他卖掉了自己的床。","他喜欢睡地板。","因为厌倦了睡地板,他攒钱买了张真正的床。","他睡在真正的床上很累。"],"answer_index":2,"explanation_cn":"Tired of sleeping on the floor, he saved up for a real bed. Tired of… 在句首表原因,意思是\"因为厌倦了睡地板,他攒钱买了张真正的床\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"Why did the young man not wake up when the bed fell?","options":["He was not on the bed","He was fast asleep and only woke when it hit the ground","He was already awake","The fall was very gentle"],"answer_index":1,"passage":"Tired of sleeping on the floor, a young man in Tehran saved up for years to buy a real bed. For the first time in his life, he became the proud owner of a bed which had springs and a mattress. Because the weather was very hot, he carried the bed onto the roof of his house. He slept very well for the first two nights, but on the third night, a storm blew up. A gust of wind swept the bed off the roof and sent it crashing into the courtyard below. The young man did not wake up until the bed had struck the ground. Although the bed was smashed to pieces, the man was miraculously unhurt. When he woke up, he was still on the mattress. Glancing at the bits of wood and metal that lay around him, the man sadly picked up the mattress and carried it into his house. After he had put it on the floor, he promptly went to sleep again.","explanation_cn":"课文说 The young man did not wake up until the bed had struck the ground,他睡得很沉,直到床落地才醒。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"What did the man do after the bed was destroyed?","options":["He picked up the mattress, took it inside, and went to sleep again","He called for help","He bought a new bed at once","He slept on the roof again"],"answer_index":0,"passage":"Tired of sleeping on the floor, a young man in Tehran saved up for years to buy a real bed. For the first time in his life, he became the proud owner of a bed which had springs and a mattress. Because the weather was very hot, he carried the bed onto the roof of his house. He slept very well for the first two nights, but on the third night, a storm blew up. A gust of wind swept the bed off the roof and sent it crashing into the courtyard below. The young man did not wake up until the bed had struck the ground. Although the bed was smashed to pieces, the man was miraculously unhurt. When he woke up, he was still on the mattress. Glancing at the bits of wood and metal that lay around him, the man sadly picked up the mattress and carried it into his house. After he had put it on the floor, he promptly went to sleep again.","explanation_cn":"课文说他伤心地捡起床垫搬进屋,放到地板上后又立刻睡着了。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"How did the dream end?","options":["Thieves stole the bed","A storm swept the bed off the roof and smashed it","He slept happily ever after on the roof","He sold the bed for a profit"],"answer_index":1,"audio":"Tired of sleeping on the floor, a young man in Tehran saved up for years to buy a real bed. For the first time in his life, he became the proud owner of a bed which had springs and a mattress. Because the weather was very hot, he carried the bed onto the roof of his house. He slept very well for the first two nights, but on the third night, a storm blew up. A gust of wind swept the bed off the roof and sent it crashing into the courtyard below. The young man did not wake up until the bed had struck the ground. Although the bed was smashed to pieces, the man was miraculously unhurt. When he woke up, he was still on the mattress. Glancing at the bits of wood and metal that lay around him, the man sadly picked up the mattress and carried it into his house. After he had put it on the floor, he promptly went to sleep again.","explanation_cn":"课文说风暴把床从屋顶刮下摔碎,美梦告终。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l49',10,NULL,'choice','{"stem":"Was the man hurt when the bed crashed down?","options":["He was never on the bed","Yes — badly","No — he was miraculously unhurt, still on the mattress","Yes — he broke his arm"],"answer_index":2,"audio":"Tired of sleeping on the floor, a young man in Tehran saved up for years to buy a real bed. For the first time in his life, he became the proud owner of a bed which had springs and a mattress. Because the weather was very hot, he carried the bed onto the roof of his house. He slept very well for the first two nights, but on the third night, a storm blew up. A gust of wind swept the bed off the roof and sent it crashing into the courtyard below. The young man did not wake up until the bed had struck the ground. Although the bed was smashed to pieces, the man was miraculously unhurt. When he woke up, he was still on the mattress. Glancing at the bits of wood and metal that lay around him, the man sadly picked up the mattress and carried it into his house. After he had put it on the floor, he promptly went to sleep again.","explanation_cn":"课文说 the man was miraculously unhurt… he was still on the mattress,他奇迹般没受伤。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l50',2,7,50,'Taken for a ride','乘车兜风','KS26 一般现在时表习惯性动作 + 状态动词(belong to/contain/need/hate/love/mean/mind…)不用进行时(教材 L50 Key structures)主考;SD26 易混词 lose/loose/miss、expect/wait for + 课文 Notes 疑问词+不定式(where to get off)、prefer to do、take sb for a ride(辅考)','我喜欢在乡间旅行,但不愿意迷路。最近我作了一次短途旅行,可这次旅行所花的时间比我预计的要长。“我要去伍德福德草地,”我一上车就对售票员说,“但我不知道它在哪儿。”“我来告诉您在哪儿下车,”售票员回答。我坐在车的前部,以便饱览农村风光。过了一会儿,车停了下来。环顾四周,我惊讶地发现自己是车上剩下的唯一乘客。“您得在这儿下车了,”售票员说,“我们只到这儿。”“这是伍德福德草地吗?”我问。“哎呀,”售票员突然说,“我忘了让您下车了。”“没关系,”我说,“我在这儿下车。”“我们现在要往回开了,”售票员说。“好吧,既然如此,我还是留在车上吧,”我回答说。','{"q":"Listen and answer — Why did the writer not get off the bus at Woodford Green?","options":["The conductor forgot to put him off, so the bus went right past it","He was asleep","He didn''t have a ticket","He wanted to see more countryside"],"answer_index":0}'::jsonb,'{"title":"一般现在时表习惯 + 状态动词不用进行时","intro":"KS26:表示习惯性、经常性或客观规律的动作,用一般现在时(These things always happen)。有一类''状态动词''——belong to、consist of、contain、need、want、hate、love、mean、mind、matter 等——表示状态而非动作,通常不用进行时(不说 are belonging)。","table":{"headers":["用法","例子"],"rows":[["习惯/经常","He usually goes to work by bus."],["客观规律","Water boils at 100°C.(总是如此)"],["状态动词·一般现在","This box contains 48 matches.(装有)"],["状态动词·不用进行时","Those papers belong to me.(不说 are belonging)"],["对比·此刻进行","Look! The bus is coming.(现在进行)"]]},"specialRules":[{"rule":"状态动词(belong to/consist of/contain/desire/detest/dislike/hate/hope/love/matter/mean/mind/need/want/wish)表状态,通常不用进行时。","mark":"状态动词不用进行时"},{"rule":"SD26 易混词:lose(丢失)/ loose(松的,形容词)/ miss(错过、想念);expect(预计…会发生)/ wait for(等候某人)。","mark":"SD26 易混词"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',1,NULL,'I love traveling in the country, but I don''t like losing my way.','我喜欢在乡间旅行,但不愿意迷路。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',2,NULL,'I went on an excursion recently, but my trip took me longer than I expected.','最近我作了一次短途旅行,可这次旅行所花的时间比我预计的要长。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',3,NULL,'''I''m going to Woodford Green,'' I said to the conductor as I got on the bus, ''but I don''t know where it is.''','“我要去伍德福德草地,”我一上车就对售票员说,“但我不知道它在哪儿。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',4,NULL,'''I''ll tell you where to get off,'' answered the conductor.','“我来告诉您在哪儿下车,”售票员回答。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',5,NULL,'I sat in the front of the bus to get a good view of the countryside.','我坐在车的前部,以便饱览农村风光。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',6,NULL,'After some time, the bus stopped. Looking round, I realized with a shock that I was the only passenger left on the bus.','过了一会儿,车停了下来。环顾四周,我惊讶地发现自己是车上剩下的唯一乘客。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',7,NULL,'''You''ll have to get off here,'' the conductor said. ''This is as far as we go.''','“您得在这儿下车了,”售票员说,“我们只到这儿。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l50',8,NULL,'''Oh dear,'' said the conductor suddenly. ''I forgot to put you off.'' ''Well, in that case, I prefer to stay on the bus,'' I answered.','“哎呀,”售票员突然说,“我忘了让您下车了。”“好吧,既然如此,我还是留在车上吧,”我回答说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
