INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l51','dessert','pudding','餐后甜点;美语 dessert,英式常说 pudding') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l51','go on a diet','',NULL,'/ɡoʊ ɑːn ə ˈdaɪət/','He decided to go on a diet.','他决定节食。','I''ve been on a diet for a week.','我节食一周了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l51','as ... as ever','',NULL,'/æz ... æz ˈevər/','Hugh was still as fat as ever.','休还是像往常一样胖。','She looks as young as ever.','她看起来还是那么年轻。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l51','so ... that','',NULL,'/soʊ ... ðæt/','His diet was so strict that he cheated.','他的节食太严格,以致偷吃。','It was so cold that the lake froze.','天太冷,湖都结冰了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l51','pay sb a visit','',NULL,'/peɪ ... ə ˈvɪzɪt/','Yesterday I paid him a visit.','昨天我拜访了他。','We''ll pay you a visit soon.','我们很快去看你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp1','choice','{"stem":"\"Things ___ so bad that he decided to go on a diet.\"(get 的过去式)","options":["getting","get","gets","got"],"answer_index":3,"stem_cn":"情况变得如此糟糕,以致他决定节食。","explanation_cn":"表示过去发生的动作用一般过去时;get 的过去式是 got。✓ Things got so bad. ✗ get / gets:一般现在;✗ getting:缺助动词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp1','choice','{"stem":"\"He ___ his diet a week ago.\"(begin 的过去式)","options":["began","beginned","begin","begins"],"answer_index":0,"stem_cn":"他一星期前开始节食。","explanation_cn":"过去发生的动作用一般过去时;begin 的过去式是 began。✓ He began his diet a week ago. ✗ begins / begin:一般现在;✗ beginned:begin 是不规则动词,没有 -ed 形式。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp1','choice','{"stem":"\"He ___ out a long list of forbidden foods.\"(write 的过去式)","options":["writes","written","wrote","writed"],"answer_index":2,"stem_cn":"他列出一张禁吃食物的长单子。","explanation_cn":"过去发生的动作用一般过去时;write 的过去式是 wrote。✓ He wrote out a long list. ✗ writed:write 是不规则动词;✗ writes:一般现在;✗ written:是过去分词,不能单独作谓语。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp1','choice','{"stem":"\"Yesterday I ___ him a visit.\"(pay 的过去式)","options":["paid","pays","pay","payed"],"answer_index":0,"stem_cn":"昨天我去拜访了他。","explanation_cn":"过去发生的动作用一般过去时;pay 的过去式是 paid。✓ Yesterday I paid him a visit. ✗ payed:pay 的正确过去式是 paid;✗ pay / pays:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp1','choice','{"stem":"\"I ___ the bell and waited.\"(ring 的过去式)","options":["ringed","rings","rung","rang"],"answer_index":3,"stem_cn":"我按了门铃等着。","explanation_cn":"过去发生的动作用一般过去时;ring 的过去式是 rang。✓ I rang the bell. ✗ ringed:ring 是不规则动词;✗ rings:一般现在;✗ rung:是过去分词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp1','choice','{"stem":"\"He ___ me into his room.\"(lead 的过去式)","options":["led","leaded","leads","lead"],"answer_index":0,"stem_cn":"他把我领进他的房间。","explanation_cn":"过去发生的动作用一般过去时;lead 的过去式是 led。✓ He led me into his room. ✗ leaded:lead 是不规则动词;✗ leads:一般现在;✗ lead:原形。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp2','choice','{"stem":"\"The magazine I ordered ___ to the wrong address.\"(过去被动:was + 过去分词)","options":["was send","sent","was sent","is sent"],"answer_index":2,"stem_cn":"我订的杂志被送错了地址。","explanation_cn":"过去发生的被动用 was/were + 过去分词;主语 magazine 单数用 was sent。✓ The magazine was sent to the wrong address. ✗ sent:缺 be 动词,不成被动;✗ was send:被动要用过去分词 sent;✗ is sent:时态应是过去。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp2','choice','{"stem":"\"A large factory ___ to the ground last year.\"(过去被动:被烧毁)","options":["was burnt","is burnt","was burn","burnt"],"answer_index":0,"stem_cn":"去年一家大工厂被烧毁了。","explanation_cn":"过去发生的被动用 was/were + 过去分词;工厂单数用 was burnt。✓ A large factory was burnt to the ground. ✗ burnt:缺 be 动词;✗ was burn:被动要用过去分词;✗ is burnt:时态应是过去(last year)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp3','choice','{"stem":"\"That boy always ___ his hand when I ask a question.\"(及物动词''举起、抬起'')","options":["rose","raise","rises","raises"],"answer_index":3,"stem_cn":"我提问时,那个男孩总举手。","explanation_cn":"raise 是及物动词,意为\"举起、抬起\",后面要接宾语;主语 boy 用 raises。✓ That boy always raises his hand. ✗ rises:是不及物动词,后面不接宾语;✗ raise:主语第三人称单数要加 s;✗ rose:是 rise 的过去式。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp3','choice','{"stem":"\"The sun ___ in the east.\"(不及物动词''升起'')","options":["raises","rises","rose","raise"],"answer_index":1,"stem_cn":"太阳从东方升起。","explanation_cn":"rise 是不及物动词,意为\"升起\",后面不接宾语;主语 sun 用 rises。✓ The sun rises in the east. ✗ raises:是及物动词要接宾语;✗ rose:过去式;✗ raise:词义和形式都不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp3','choice','{"stem":"\"I always ___ at six o''clock.\"(不及物动词''起床'')","options":["raised","raise","rise","rose"],"answer_index":2,"stem_cn":"我总是六点钟起床。","explanation_cn":"rise 是不及物动词,意为\"起床、升起\";主语 I 用原形 rise。✓ I always rise at six o''clock. ✗ raise:是及物动词(举起某物);✗ rose:过去式;✗ raised:raise 的过去式。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp4','choice','{"stem":"\"Please ___ those parcels on the floor.\"(及物动词''放置、搁''某物)","options":["lay","lied","lie","lies"],"answer_index":0,"stem_cn":"请把那些包裹放在地板上。","explanation_cn":"lay 是及物动词,意为\"放置、搁\",后面接宾语(those parcels)。✓ Please lay those parcels on the floor. ✗ lie:是不及物动词(躺),不接宾语;✗ lies / lied:形式和词义都不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp4','choice','{"stem":"\"It''s nicer to ___ in bed on a cold morning.\"(不及物动词''躺'')","options":["laid","lie","lay","lays"],"answer_index":1,"stem_cn":"冷天早上躺在床上更舒服。","explanation_cn":"lie 是不及物动词,意为\"躺\",后面不接宾语。✓ It''s nicer to lie in bed on a cold morning. ✗ lay:是及物动词(放置某物);✗ lays / laid:形式和词义都不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp4','choice','{"stem":"\"Where''s my book? I ___ it on the shelf a moment ago.\"(刚才把某物''放好'',用''放置''的过去式)","options":["laid","lied","lay","lain"],"answer_index":0,"stem_cn":"我的书呢?我刚把它放在架子上了。","explanation_cn":"\"放置\"用及物动词 lay,其过去式是 laid。✓ I laid it on the shelf a moment ago. ✗ lay:是原形(或 lie 的过去式,词义不对);✗ lied:是\"说谎\"的过去式;✗ lain:是 lie(躺)的过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp5','choice','{"stem":"\"Arsenal ___ Manchester United last Saturday.\"(战胜某人/某队,后接对手)","options":["beated","beat","win","won"],"answer_index":1,"stem_cn":"上周六阿森纳队战胜了曼联队。","explanation_cn":"beat 意为\"战胜某人/某队\",后面接对手(Manchester United)。✓ Arsenal beat Manchester United last Saturday. ✗ won:win 后接比赛/奖,不接对手;✗ win:时态应是过去;✗ beated:beat 的过去式仍是 beat。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp5','choice','{"stem":"\"Arsenal ___ the game.\"(赢得比赛/奖品,后接比赛或奖)","options":["won","beat","winned","win"],"answer_index":0,"stem_cn":"阿森纳队赢了这场比赛。","explanation_cn":"win 意为\"赢得(比赛、奖品)\",后面接比赛或奖(the game);win 的过去式是 won。✓ Arsenal won the game. ✗ beat:后接对手不接比赛;✗ win:时态应是过去;✗ winned:win 是不规则动词。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp6','choice','{"stem":"\"Things got ___ bad that he decided to go on a diet.\"(如此…以致…)","options":["very","too","such","so"],"answer_index":3,"stem_cn":"情况变得如此糟糕,以致他决定节食。","explanation_cn":"\"如此…以致…\"用 so + 形容词 + that。✓ Things got so bad that he decided to go on a diet. ✗ such:后面直接跟形容词时用 so 不用 such;✗ very / too:不与 that 从句构成\"如此…以致…\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',5,'am2_l51_gp6','choice','{"stem":"\"He decided to go ___ a diet.\"(实行节食的固定搭配)","options":["on","in","at","for"],"answer_index":0,"stem_cn":"他决定实行节食。","explanation_cn":"\"实行节食\"的固定搭配是 go on a diet。✓ He decided to go on a diet. ✗ in / at / for:不与 diet 这样搭配。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',6,NULL,'choice','{"stem":"美语里\"糖果\"常说:","options":["candy","confection","lollies","sweets"],"answer_index":0,"explanation_cn":"美语\"糖果\"常说 candy;英式说 sweets。✓ a bag of candy 一袋糖果。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',6,NULL,'choice','{"stem":"美语里\"(甜)饼干\"常说:","options":["biscuit","cookie","tea biscuit","cracker cake"],"answer_index":1,"explanation_cn":"美语\"(甜)饼干\"常说 cookie;英式说 biscuit。✓ a chocolate cookie 一块巧克力饼干。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',6,NULL,'choice','{"stem":"virtue 的意思是:","options":["美德,优点","习惯","礼貌","恶习"],"answer_index":0,"explanation_cn":"virtue = 美德、优点。✓ Reward for virtue 对美德的奖赏。\n顺带记:恶习 = vice;习惯 = habit;礼貌 = politeness."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',6,NULL,'choice','{"stem":"diet 的意思是:","options":["锻炼","睡眠","药物","节食;日常饮食"],"answer_index":3,"explanation_cn":"diet = 节食;(日常)饮食。✓ go on a diet 实行节食。\n顺带记:锻炼 = exercise;睡眠 = sleep;药物 = medicine."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',6,NULL,'choice','{"stem":"strict 的意思是:","options":["礼貌的","懒惰的","严格的","宽松的"],"answer_index":2,"explanation_cn":"strict = 严格的。✓ his diet was so strict 他的节食那么严格。\n顺带记:宽松的 = loose;礼貌的 = polite;懒惰的 = lazy."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',6,NULL,'choice','{"stem":"occasionally 的意思是:","options":["偶尔地","从不","立刻","经常地"],"answer_index":0,"explanation_cn":"occasionally = 偶尔地。✓ reward himself occasionally 偶尔奖赏自己。\n顺带记:从不 = never;经常地 = often;立刻 = immediately."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',7,NULL,'cloze','{"stem":"第 1 空","context":"My friend Hugh got so fat that he decided to go on a diet. Yesterday I ___1___ him a visit. I ___2___ the bell. Hugh ___3___ me into his room and ___4___ a large parcel under his desk.","blank_no":1,"options":["paid","payed","pay","pays"],"answer_index":0,"explanation_cn":"过去发生的动作用一般过去时;pay 的过去式是 paid。✓ Yesterday I paid him a visit.\n✗ payed:正确形式是 paid;✗ pay / pays:一般现在。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',7,NULL,'cloze','{"stem":"第 2 空","context":"My friend Hugh got so fat that he decided to go on a diet. Yesterday I ___1___ him a visit. I ___2___ the bell. Hugh ___3___ me into his room and ___4___ a large parcel under his desk.","blank_no":2,"options":["rang","ringed","rung","rings"],"answer_index":0,"explanation_cn":"过去发生的动作用一般过去时;ring 的过去式是 rang。✓ I rang the bell.\n✗ ringed:ring 是不规则动词;✗ rung:过去分词;✗ rings:一般现在。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',7,NULL,'cloze','{"stem":"第 3 空","context":"My friend Hugh got so fat that he decided to go on a diet. Yesterday I ___1___ him a visit. I ___2___ the bell. Hugh ___3___ me into his room and ___4___ a large parcel under his desk.","blank_no":3,"options":["led","leaded","lead","leads"],"answer_index":0,"explanation_cn":"过去发生的动作用一般过去时;lead 的过去式是 led。✓ Hugh led me into his room.\n✗ leaded:不规则动词;✗ lead:原形;✗ leads:一般现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',7,NULL,'cloze','{"stem":"第 4 空","context":"My friend Hugh got so fat that he decided to go on a diet. Yesterday I ___1___ him a visit. I ___2___ the bell. Hugh ___3___ me into his room and ___4___ a large parcel under his desk.","blank_no":4,"options":["hid","hided","hide","hidden"],"answer_index":0,"explanation_cn":"过去发生的动作用一般过去时;hide 的过去式是 hid。✓ hid a large parcel under his desk.\n✗ hided:不规则动词;✗ hide:原形;✗ hidden:过去分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',8,NULL,'choice','{"stem":"Why did Hugh decide to go on a diet?","options":["His doctor ordered it","His friend told him to","He had always been fat and things got so bad","He wanted to save money"],"answer_index":2,"explanation_cn":"课文说 Hugh has always been fat, but things got so bad… that he decided to go on a diet。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',8,NULL,'choice','{"stem":"What did Hugh hide under his desk?","options":["His homework","A large parcel of chocolate and candy","A magazine","His diet list"],"answer_index":1,"explanation_cn":"课文说他 hurriedly hid a large parcel,里面装着 five large bars of chocolate and three bags of candy。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',8,NULL,'choice','{"stem":"Why did Hugh say he had to reward himself occasionally?","options":["His diet was so strict","He had lost a lot of weight","It was his birthday","He had done a lot of work"],"answer_index":0,"explanation_cn":"课文说 his diet was so strict that he had to reward himself occasionally,节食太严格才偶尔奖赏自己。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',9,NULL,'choice','{"stem":"你想说\"昨天我去拜访了他\"(过去发生的动作用一般过去时):","options":["Yesterday I will pay him a visit.","Yesterday I am paying him a visit.","Yesterday I pay him a visit.","Yesterday I paid him a visit."],"answer_index":3,"explanation_cn":"过去发生的动作用一般过去时(pay→paid)。✓ Yesterday I paid him a visit. 场合:叙述昨天做过的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',9,NULL,'choice','{"stem":"你想说\"他的节食太严格了,以致他得偶尔奖赏自己\"(如此…以致…用 so...that):","options":["His diet was so strict that he had to reward himself.","His diet was such strict that he had to reward himself.","His diet was very strict that he had to reward himself.","His diet was too strict that he had to reward himself."],"answer_index":0,"explanation_cn":"\"如此…以致…\"用 so + 形容词 + that 从句(strict 是形容词,前面用 so)。✓ His diet was so strict that he had to reward himself. 场合:说某事程度深到造成某个结果。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',9,NULL,'choice','{"stem":"你想说\"我提问时那个男孩总举手\"(举手用及物动词 raise):","options":["That boy always rises his hand when I ask a question.","That boy always raise his hand when I ask a question.","That boy always raises his hand when I ask a question.","That boy always is raising his hand when I ask a question."],"answer_index":2,"explanation_cn":"\"举手\"是举起东西,raise 后面要接举起的东西(his hand),he/she 等用 raises;rise 后面不接东西,不能说 rise his hand。✓ That boy always raises his hand when I ask a question. 场合:说举手、举起某物。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"virtue 的意思是:","options":["美德,优点","恶习","习惯","礼貌"],"answer_index":0,"explanation_cn":"virtue = 美德、优点。✓ Reward for virtue 对美德的奖赏。\n顺带记:恶习 = vice;习惯 = habit;礼貌 = politeness."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"diet 的意思是:","options":["锻炼","睡眠","节食;日常饮食","药物"],"answer_index":2,"explanation_cn":"diet = 节食;(日常)饮食。✓ go on a diet 实行节食。\n顺带记:锻炼 = exercise;睡眠 = sleep;药物 = medicine."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"\"Things ___ so bad that he decided to go on a diet.\"(get 的过去式)","options":["got","gets","getting","get"],"answer_index":0,"stem_cn":"情况变得如此糟糕,以致他决定节食。","explanation_cn":"过去发生的动作用一般过去时;get 的过去式是 got。✓ Things got so bad.\n✗ get / gets:一般现在;✗ getting:缺助动词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"\"The magazine I ordered ___ to the wrong address.\"(过去被动)","options":["sent","is sent","was sent","was send"],"answer_index":2,"stem_cn":"我订的杂志被送错了地址。","explanation_cn":"过去发生的被动用 was/were + 过去分词;magazine 单数用 was sent。✓ The magazine was sent to the wrong address.\n✗ sent:缺 be 动词;✗ was send:被动要用过去分词;✗ is sent:时态应是过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"\"as fat as ever\" 这个短语的意思是:","options":["不再胖了","像以往一样胖","比以前更胖了","从来不胖"],"answer_index":1,"explanation_cn":"as fat as ever = 像以往一样胖(as … as ever 表\"依旧和从前一样\")。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"\"go on a diet\" 这个短语的意思是:","options":["实行节食","去看医生","去锻炼","去度假"],"answer_index":0,"explanation_cn":"go on a diet = 实行节食、开始节食。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"What foods were on Hugh''s forbidden list?","options":["Only vegetables","Most of the things he loves — butter, potatoes, rice, beer, milk, chocolate, candy","Fast food only","Nothing at all"],"answer_index":1,"passage":"My friend, Hugh, has always been fat, but things got so bad recently that he decided to go on a diet. He began his diet a week ago. First of all, he wrote out a long list of all the foods which were forbidden. The list included most of the things Hugh loves: butter, potatoes, rice, beer, milk, chocolate, and candy. Yesterday I paid him a visit. I rang the bell and was not surprised to see that Hugh was still as fat as ever. He led me into his room and hurriedly hid a large parcel under his desk. It was obvious that he was very embarrassed. When I asked him what he was doing, he smiled guiltily and then put the parcel on the desk. He explained that his diet was so strict that he had to reward himself occasionally. Then he showed me the contents of the parcel. It contained five large bars of chocolate and three bags of candy!","explanation_cn":"课文说 The list included most of the things Hugh loves: butter, potatoes, rice, beer, milk, chocolate, and candy。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"Was Hugh thinner when the writer visited?","options":["Yes, much thinner","The text doesn''t say","Yes, a little thinner","No, he was still as fat as ever"],"answer_index":3,"passage":"My friend, Hugh, has always been fat, but things got so bad recently that he decided to go on a diet. He began his diet a week ago. First of all, he wrote out a long list of all the foods which were forbidden. The list included most of the things Hugh loves: butter, potatoes, rice, beer, milk, chocolate, and candy. Yesterday I paid him a visit. I rang the bell and was not surprised to see that Hugh was still as fat as ever. He led me into his room and hurriedly hid a large parcel under his desk. It was obvious that he was very embarrassed. When I asked him what he was doing, he smiled guiltily and then put the parcel on the desk. He explained that his diet was so strict that he had to reward himself occasionally. Then he showed me the contents of the parcel. It contained five large bars of chocolate and three bags of candy!","explanation_cn":"课文说 I was not surprised to see that Hugh was still as fat as ever,他一点没瘦。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"What was in the parcel Hugh hid?","options":["Diet books","A birthday cake","Five bars of chocolate and three bags of candy","New clothes"],"answer_index":2,"audio":"My friend, Hugh, has always been fat, but things got so bad recently that he decided to go on a diet. He began his diet a week ago. First of all, he wrote out a long list of all the foods which were forbidden. The list included most of the things Hugh loves: butter, potatoes, rice, beer, milk, chocolate, and candy. Yesterday I paid him a visit. I rang the bell and was not surprised to see that Hugh was still as fat as ever. He led me into his room and hurriedly hid a large parcel under his desk. It was obvious that he was very embarrassed. When I asked him what he was doing, he smiled guiltily and then put the parcel on the desk. He explained that his diet was so strict that he had to reward himself occasionally. Then he showed me the contents of the parcel. It contained five large bars of chocolate and three bags of candy!","explanation_cn":"课文说 It contained five large bars of chocolate and three bags of candy。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l51',10,NULL,'choice','{"stem":"How did Hugh look when the writer caught him?","options":["Proud","Relaxed","Angry","Embarrassed, and he smiled guiltily"],"answer_index":3,"audio":"My friend, Hugh, has always been fat, but things got so bad recently that he decided to go on a diet. He began his diet a week ago. First of all, he wrote out a long list of all the foods which were forbidden. The list included most of the things Hugh loves: butter, potatoes, rice, beer, milk, chocolate, and candy. Yesterday I paid him a visit. I rang the bell and was not surprised to see that Hugh was still as fat as ever. He led me into his room and hurriedly hid a large parcel under his desk. It was obvious that he was very embarrassed. When I asked him what he was doing, he smiled guiltily and then put the parcel on the desk. He explained that his diet was so strict that he had to reward himself occasionally. Then he showed me the contents of the parcel. It contained five large bars of chocolate and three bags of candy!","explanation_cn":"课文说 It was obvious that he was very embarrassed… he smiled guiltily,他很尴尬、内疚地笑。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l52',2,7,52,'A pretty carpet','漂亮的地毯','KS28 现在完成时(have done,完成/次数/结果)vs 现在完成进行时(have been doing,一直在进行)(教材 L52 Key structures)主考;SD28 形容词与副词辨析(sings beautifully、hard≠hardly、late≠lately、high≠highly、near≠nearly)+ 课文 get…in order、to make matters worse、in your spare time(辅考)','我们刚刚搬进一所新房子,我辛辛苦苦地干了整整一个上午。我试图把新房间收拾整齐,但这并不容易,因为我有 1,000 多本书。更糟糕的是,房间还非常小,所以我暂时把书放在了地板上。这会儿,书把地板的每一点空隙都占据了,我实际上是踩着这些书进出房间的。几分钟前,我妹妹帮我把一个旧书橱抬上了楼。她走进我的房间,当她看到地板上那些书时,大吃一惊。“这是我见过的最漂亮的地毯,”她说。她盯着“地毯”看了一会儿,又说:“你根本用不着书橱,空闲时你可以坐在这儿读地毯!”','{"q":"Listen and answer — What is the writer''s carpet made of?","options":["His own books, spread all over the floor","Real wool","Old newspapers","Colored tiles"],"answer_index":0}'::jsonb,'{"title":"现在完成时 vs 现在完成进行时","intro":"KS28:现在完成时(have/has + 过去分词)强调动作已完成、次数,或对现在的结果;现在完成进行时(have/has been + doing)强调动作在一段时间里一直在进行(常常还在继续)。","table":{"headers":["时态","例子"],"rows":[["现在完成(次数/结果)","He has rung me five times.(打了 5 次)"],["现在完成进行(一直在做)","He has been ringing me all morning.(一直在打)"],["现在完成(读过几遍)","I have read it five times."],["现在完成进行(读了一下午)","I have been reading all afternoon."],["否定·至今","It hasn''t rained for six weeks."]]},"specialRules":[{"rule":"现在完成进行时 = have/has been + 现在分词,强调持续;不能带明确的次数(不说 has been ringing five times)。","mark":"have been doing"},{"rule":"SD28 形容词 vs 副词:修饰动词用副词(sings beautifully、works slowly)。注意 hard(努力,形容词副词同形)≠ hardly(几乎不);late(晚)≠ lately(最近);high(高)≠ highly(高度地);near(近)≠ nearly(差点)。","mark":"SD28 副词辨析"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',1,NULL,'We have just moved into a new house and I have been working hard all morning.','我们刚搬进一所新房子,我辛辛苦苦地干了整整一个上午。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',2,NULL,'I have been trying to get my new room in order. This has not been easy because I own over a thousand books.','我试图把新房间收拾整齐,但这并不容易,因为我有 1,000 多本书。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',3,NULL,'To make matters worse, the room is rather small, so I have temporarily put my books on the floor.','更糟糕的是,房间还非常小,所以我暂时把书放在了地板上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',4,NULL,'At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room.','这会儿,书把地板的每一点空隙都占据了,我实际上是踩着这些书进出房间的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',5,NULL,'A short while ago, my sister helped me to carry one of my old bookcases up the stairs.','几分钟前,我妹妹帮我把一个旧书橱抬上了楼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',6,NULL,'She went into my room and got a big surprise when she saw all those books on the floor.','她走进我的房间,当她看到地板上那些书时,大吃一惊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',7,NULL,'''This is the prettiest carpet I have ever seen,'' she said.','“这是我见过的最漂亮的地毯,”她说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l52',8,NULL,'She gazed at it for some time then added, ''You don''t need bookcases at all. You can sit here in your spare time and read the carpet!''','她盯着“地毯”看了一会儿,又说:“你根本用不着书橱,空闲时你可以坐在这儿读地毯!”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','temporarily','/ˈtempərerɪli/','adv','暂时地','temporarily put my books on the floor') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
