INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','space','/speɪs/','n','空间,地方','every inch of floor space') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','actually','/ˈæktʃuəli/','adv','实际上,竟然','I actually have to walk on them') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','bookcase','/ˈbʊkkeɪs/','n','书橱,书架','carry one of my old bookcases') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','gaze','/ɡeɪz/','v','凝视,盯着看','She gazed at it for some time') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','surprise','/sərˈpraɪz/','n','惊奇,意外','got a big surprise') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','spare','/sper/','adj','空闲的,多余的','in your spare time') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','order','/ˈɔːrdər/','n','整齐,秩序','get my room in order') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l52','rather','/ˈræðər/','adv','相当,颇','the room is rather small') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l52_gp1','am2_l52','现在完成时(have/has + 过去分词)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l52_gp2','am2_l52','现在完成进行时(have/has been + doing)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l52_gp3','am2_l52','现在完成 vs 现在完成进行(对比)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l52_gp4','am2_l52','形容词 vs 副词(SD28)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l52_gp5','am2_l52','易混副词 hard/hardly、late/lately(SD28)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l52_gp6','am2_l52','get…in order / make matters worse(辅考·课文)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l52','elevator','lift','电梯;美语 elevator,英式 lift') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l52','apartment','flat','公寓;美语 apartment,英式 flat') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l52','first floor','ground floor','一楼;美语 first floor 即地面层,英式叫 ground floor') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l52','closet','cupboard','壁橱、储物间;美语 closet,英式 cupboard') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l52','get ... in order','',NULL,'/ɡet ɪn ˈɔːrdər/','I have been trying to get my room in order.','我一直想把房间整理好。','Please get your papers in order.','请把你的文件整理好。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l52','to make matters worse','',NULL,'/meɪk ˈmætərz wɜːrs/','To make matters worse, the room is small.','更糟的是,房间很小。','To make matters worse, it started to rain.','更糟的是,开始下雨了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l52','at the moment','',NULL,'/æt ðə ˈmoʊmənt/','At the moment, books cover the floor.','此刻,书铺满了地板。','I''m rather busy at the moment.','我此刻挺忙。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l52','in one''s spare time','',NULL,'/ɪn ... sper taɪm/','Read the carpet in your spare time.','空闲时读读地毯吧。','I paint in my spare time.','我空闲时画画。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp1','choice','{"stem":"\"We ___ just moved into a new house.\"(现在完成时:刚刚做完)","options":["have","did","will","are"],"answer_index":0,"stem_cn":"我们刚搬进一所新房子。","explanation_cn":"表示\"刚刚做完、对现在有影响\"用现在完成时 have/has + 过去分词;主语 We 用 have。✓ We have just moved into a new house. ✗ are:be 动词不构成完成时;✗ did:一般过去;✗ will:将来。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp1','choice','{"stem":"\"This is the prettiest carpet I have ever ___.\"(现在完成时:see 的过去分词)","options":["see","saw","seeing","seen"],"answer_index":3,"stem_cn":"这是我见过的最漂亮的地毯。","explanation_cn":"现在完成时用 have + 过去分词;see 的过去分词是 seen。✓ the prettiest carpet I have ever seen. ✗ saw:过去式不能跟在 have 后;✗ see:原形;✗ seeing:现在分词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp1','choice','{"stem":"\"He has ___ me up five times since 12 o''clock.\"(现在完成时:ring 的过去分词)","options":["rung","ringing","ring","rang"],"answer_index":0,"stem_cn":"从 12 点起他给我打了 5 次电话。","explanation_cn":"现在完成时用 has + 过去分词;ring 的过去分词是 rung。✓ He has rung me up five times. ✗ rang:过去式不能跟 has;✗ ring:原形;✗ ringing:现在分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp1','choice','{"stem":"\"It ___ rained for six weeks.\"(现在完成时否定:一直没下)","options":["isn''t","won''t","didn''t","hasn''t"],"answer_index":3,"stem_cn":"已经 6 个星期没下雨了。","explanation_cn":"\"到现在为止一直没…\"用现在完成时否定 hasn''t + 过去分词;主语 It 用 hasn''t。✓ It hasn''t rained for six weeks. ✗ isn''t:be 动词不构成完成时;✗ didn''t:一般过去;✗ won''t:将来。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp2','choice','{"stem":"\"I ___ working hard all morning.\"(现在完成进行时:一直在做)","options":["was","am","have been","have"],"answer_index":2,"stem_cn":"我整个上午一直在干活。","explanation_cn":"\"某段时间内一直在做\"用现在完成进行时 have/has been + 现在分词;主语 I 用 have been。✓ I have been working hard all morning. ✗ have:后面要加 been working;✗ am:现在进行不含\"一整个上午\"的完成意味;✗ was:过去。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp2','choice','{"stem":"\"It has ___ raining hard since yesterday.\"(现在完成进行时:一直在下)","options":["was","be","being","been"],"answer_index":3,"stem_cn":"从昨天起一直在下大雨。","explanation_cn":"现在完成进行时结构是 has been + 现在分词,中间的词是 been。✓ It has been raining hard since yesterday. ✗ be / being:形式不对;✗ was:与 has 不搭配。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp2','choice','{"stem":"\"He has been ___ me up all morning.\"(现在完成进行时:ring 的 -ing 形式)","options":["rung","ring","ringing","rang"],"answer_index":2,"stem_cn":"整个上午他一直在给我打电话。","explanation_cn":"现在完成进行时用 has been + 现在分词;ring 的现在分词是 ringing。✓ He has been ringing me up all morning. ✗ rung:过去分词(用于现在完成时);✗ rang:过去式;✗ ring:原形。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp2','choice','{"stem":"\"He ___ been staying at this hotel for three weeks.\"(现在完成进行时,he 后面用哪个助动词)","options":["is","was","have","has"],"answer_index":3,"stem_cn":"他一直住在这家酒店有 3 周了。","explanation_cn":"现在完成进行时 has been + 现在分词;主语 He 用助动词 has。✓ He has been staying at this hotel for three weeks. ✗ have:主语第三人称单数不用 have;✗ is:不构成完成进行;✗ was:过去。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp3','choice','{"stem":"\"He ___ me up five times since 12 o''clock.\"(强调打了几次·结果:用现在完成时)","options":["rings","has been ringing","has rung","is ringing"],"answer_index":2,"stem_cn":"从 12 点起他给我打了 5 次电话(强调次数)。","explanation_cn":"强调\"打了几次\"(有具体次数、看结果)用现在完成时。✓ He has rung me up five times since 12 o''clock. ✗ has been ringing:现在完成进行不与具体次数连用;✗ rings / is ringing:时态不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp3','choice','{"stem":"\"He ___ me up all morning.\"(强调整个上午一直在打:用现在完成进行时)","options":["has rung","rings","rang","has been ringing"],"answer_index":3,"stem_cn":"整个上午他一直在给我打电话(强调持续)。","explanation_cn":"强调\"整个上午一直在打\"(持续进行)用现在完成进行时。✓ He has been ringing me up all morning. ✗ has rung:强调结果/次数,不强调持续;✗ rings / rang:时态不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp4','choice','{"stem":"\"She has a beautiful voice. She sings ___.\"(修饰动词 sing,要用副词)","options":["beauty","more beautiful","beautifully","beautiful"],"answer_index":2,"stem_cn":"她嗓音很美,她唱歌很动听。","explanation_cn":"sing(唱)是动词,修饰动词要用副词 beautifully。✓ She sings beautifully. ✗ beautiful:形容词,修饰名词(a beautiful voice);✗ beauty:名词;✗ more beautiful:比较级形容词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp4','choice','{"stem":"\"He is a slow worker. He works ___.\"(修饰动词 work,要用副词)","options":["slower","slowly","slowness","slow"],"answer_index":1,"stem_cn":"他是个迟钝的人,工作很慢。","explanation_cn":"work(工作)是动词,修饰动词要用副词 slowly。✓ He works slowly. ✗ slow:形容词(a slow worker);✗ slower:比较级;✗ slowness:名词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp4','choice','{"stem":"\"She dusted the furniture very ___.\"(修饰动词 dust,要用副词)","options":["care","careful","carefulness","carefully"],"answer_index":3,"stem_cn":"她非常仔细地掸去家具上的灰。","explanation_cn":"dust(掸灰)是动词,修饰动词要用副词 carefully。✓ She dusted the furniture very carefully. ✗ careful:形容词;✗ care:名词/动词;✗ carefulness:名词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp5','choice','{"stem":"\"He is a hard worker. He works very ___.\"(努力地,这个词形容词副词同形)","options":["hard","hardly","hardness","more hardly"],"answer_index":0,"stem_cn":"他很勤奋,工作非常努力。","explanation_cn":"\"努力地\"这个词形容词、副词同形,都是 hard(没有 -ly)。✓ He works very hard. ✗ hardly:意思是\"几乎不\",词义相反;✗ hardness:名词;✗ more hardly:词义和形式都不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp5','choice','{"stem":"\"He ___ ever does any work.\"(几乎不、几乎没)","options":["lately","hardly","hard","nearly"],"answer_index":1,"stem_cn":"他几乎从不干活。","explanation_cn":"\"几乎不、几乎没\"用 hardly(它不是 hard 的副词形式)。✓ He hardly ever does any work. ✗ hard:意思是\"努力地\",词义相反;✗ nearly:差点;✗ lately:最近。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp5','choice','{"stem":"\"Have you travelled by train ___?\"(最近、近来)","options":["later","lastly","lately","late"],"answer_index":2,"stem_cn":"最近你有没有乘火车旅行?","explanation_cn":"\"最近、近来\"用 lately(不是 late)。✓ Have you travelled by train lately? ✗ late:意思是\"晚\";✗ later:以后;✗ lastly:最后(列举时用)。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp6','choice','{"stem":"\"To make matters ___, the room is rather small.\"(更糟糕的是,bad 的比较级)","options":["worse","worst","bad","badly"],"answer_index":0,"stem_cn":"更糟糕的是,房间相当小。","explanation_cn":"\"更糟糕的是\"用 to make matters worse;worse 是 bad 的比较级。✓ To make matters worse, the room is rather small. ✗ bad:原级;✗ badly:副词;✗ worst:最高级。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',5,'am2_l52_gp6','choice','{"stem":"\"You can sit here in your ___ time and read.\"(空闲的、空余的时间)","options":["empty","free of","rest","spare"],"answer_index":3,"stem_cn":"你空闲时可以坐这儿看。","explanation_cn":"\"空闲的、空余的时间\"用 spare time。✓ You can sit here in your spare time. ✗ free of:搭配不对(free time 才对,free of 是\"免于\");✗ empty / rest:不与 time 这样搭配表\"空闲\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',6,NULL,'choice','{"stem":"美语里\"电梯\"常说:","options":["lift","climber","elevator","hoist"],"answer_index":2,"explanation_cn":"美语\"电梯\"常说 elevator;英式说 lift。✓ take the elevator 乘电梯。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',6,NULL,'choice','{"stem":"美语里\"(一套)公寓\"常说:","options":["flat","unit house","block","apartment"],"answer_index":3,"explanation_cn":"美语\"(一套)公寓\"常说 apartment;英式说 flat。✓ a small apartment 一套小公寓。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',6,NULL,'choice','{"stem":"temporarily 的意思是:","options":["仔细地","永久地","暂时地","立刻"],"answer_index":2,"explanation_cn":"temporarily = 暂时地。✓ temporarily put my books on the floor 暂时把书放地上。\n顺带记:永久地 = permanently;立刻 = immediately;仔细地 = carefully."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',6,NULL,'choice','{"stem":"inch 的意思是:","options":["公里","英寸(度量单位)","重量","面积"],"answer_index":1,"explanation_cn":"inch = 英寸(长度单位,约 2.54 厘米)。✓ every inch of floor space 每一寸地面。\n顺带记:公里 = kilometer;重量 = weight;面积 = area."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',6,NULL,'choice','{"stem":"space 的意思是:","options":["空间,地方","声音","速度","时间"],"answer_index":0,"explanation_cn":"space = 空间、地方。✓ every inch of floor space 每一寸地面空间。\n顺带记:时间 = time;速度 = speed;声音 = sound."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',6,NULL,'choice','{"stem":"actually 的意思是:","options":["很少","也许","实际上,竟然","从不"],"answer_index":2,"explanation_cn":"actually = 实际上;(表示意外)竟然。✓ I actually have to walk on them 我实际上得踩着它们走。\n顺带记:很少 = seldom;从不 = never;也许 = perhaps."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',7,NULL,'cloze','{"stem":"第 1 空","context":"We have just moved into a new house. I ___1___ working hard all morning, and it ___2___ not been easy because I own over a thousand books. ''This is the prettiest carpet I have ever ___3___,'' my sister said. ''You ___4___ reading all afternoon — now read the carpet!''","blank_no":1,"options":["have been","have","am","was"],"answer_index":0,"explanation_cn":"\"某段时间内一直在做\"用现在完成进行时 have been + 现在分词。✓ I have been working hard all morning.\n✗ have:后面要加 been;✗ am:不含\"一整个上午\"的完成意味;✗ was:过去。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',7,NULL,'cloze','{"stem":"第 2 空","context":"We have just moved into a new house. I ___1___ working hard all morning, and it ___2___ not been easy because I own over a thousand books. ''This is the prettiest carpet I have ever ___3___,'' my sister said. ''You ___4___ reading all afternoon — now read the carpet!''","blank_no":2,"options":["has","is","was","have"],"answer_index":0,"explanation_cn":"\"到现在一直不容易\"用现在完成时;主语 it 用 has。✓ it has not been easy.\n✗ is:be 动词不构成完成时;✗ was:过去;✗ have:主语单数不用 have。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',7,NULL,'cloze','{"stem":"第 3 空","context":"We have just moved into a new house. I ___1___ working hard all morning, and it ___2___ not been easy because I own over a thousand books. ''This is the prettiest carpet I have ever ___3___,'' my sister said. ''You ___4___ reading all afternoon — now read the carpet!''","blank_no":3,"options":["seen","saw","see","seeing"],"answer_index":0,"explanation_cn":"现在完成时用 have + 过去分词;see 的过去分词是 seen。✓ the prettiest carpet I have ever seen.\n✗ saw:过去式;✗ see:原形;✗ seeing:现在分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',7,NULL,'cloze','{"stem":"第 4 空","context":"We have just moved into a new house. I ___1___ working hard all morning, and it ___2___ not been easy because I own over a thousand books. ''This is the prettiest carpet I have ever ___3___,'' my sister said. ''You ___4___ reading all afternoon — now read the carpet!''","blank_no":4,"options":["have been","have","are","did"],"answer_index":0,"explanation_cn":"\"一下午一直在读\"用现在完成进行时 have been + 现在分词。✓ You have been reading all afternoon.\n✗ have:后面要加 been;✗ are:现在进行不含\"一整个下午\"的完成意味;✗ did:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',8,NULL,'choice','{"stem":"What has the writer been doing all morning?","options":["Working hard to get his new room in order","Sleeping","Reading a novel","Cooking"],"answer_index":0,"explanation_cn":"课文说 I have been working hard all morning… trying to get my new room in order。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',8,NULL,'choice','{"stem":"Why are the books on the floor?","options":["He is selling them","The bookcases broke","He likes them there","He has over a thousand books and the room is too small"],"answer_index":3,"explanation_cn":"课文说 I own over a thousand books… the room is rather small, so I have temporarily put my books on the floor。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',8,NULL,'choice','{"stem":"What did his sister call the books on the floor?","options":["A waste of money","The prettiest carpet she had ever seen","A fire hazard","A terrible mess"],"answer_index":1,"explanation_cn":"课文说妹妹 said ''This is the prettiest carpet I have ever seen.''"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',9,NULL,'choice','{"stem":"你想说\"我整个上午一直在干活\"(强调一直在进行,用现在完成进行时):","options":["I am been working hard all morning.","I have been working hard all morning.","I have being working hard all morning.","I have been work hard all morning."],"answer_index":1,"explanation_cn":"\"一整个上午一直在做\"用现在完成进行时 have been + 现在分词。✓ I have been working hard all morning. 场合:强调动作持续了一段时间。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',9,NULL,'choice','{"stem":"你想说\"《雾都孤儿》我已经读过 5 遍了\"(强调读过几遍,用现在完成时):","options":["I have read ''Oliver Twist'' five times.","I have been reading ''Oliver Twist'' five times.","I have read ''Oliver Twist'' since five times.","I am read ''Oliver Twist'' five times."],"answer_index":0,"explanation_cn":"强调\"读过几遍\"(有具体次数)用现在完成时 have + 过去分词,不用完成进行时。✓ I have read ''Oliver Twist'' five times. 场合:说至今做过某事多少次。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',9,NULL,'choice','{"stem":"你想说\"他工作很努力\"(修饰动词 work 用 hard,不是 hardly):","options":["He works very hardly.","He works very hardness.","He works very hard.","He work very hard."],"answer_index":2,"explanation_cn":"\"努力地\"用 hard(形容词副词同形);hardly 意思是\"几乎不\",不能用。✓ He works very hard. 场合:说某人工作很卖力。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"space 的意思是:","options":["空间,地方","时间","声音","速度"],"answer_index":0,"explanation_cn":"space = 空间、地方。✓ every inch of floor space 每一寸地面空间。\n顺带记:时间 = time;速度 = speed;声音 = sound."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"actually 的意思是:","options":["很少","也许","实际上,竟然","从不"],"answer_index":2,"explanation_cn":"actually = 实际上;(表意外)竟然。✓ I actually have to walk on them 我实际上得踩着走。\n顺带记:很少 = seldom;从不 = never;也许 = perhaps."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"\"I ___ working hard all morning.\"(现在完成进行时)","options":["am","was","have","have been"],"answer_index":3,"stem_cn":"我整个上午一直在干活。","explanation_cn":"\"某段时间内一直在做\"用现在完成进行时 have been + 现在分词。✓ I have been working hard all morning.\n✗ have:后面要加 been;✗ am:不含完成意味;✗ was:过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"\"It ___ rained for six weeks.\"(现在完成时否定)","options":["hasn''t","won''t","isn''t","didn''t"],"answer_index":0,"stem_cn":"已经 6 个星期没下雨了。","explanation_cn":"\"到现在为止一直没…\"用现在完成时否定 hasn''t;主语 It 用 hasn''t。✓ It hasn''t rained for six weeks.\n✗ isn''t:不构成完成时;✗ didn''t:一般过去;✗ won''t:将来。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"\"to make matters worse\" 这个短语的意思是:","options":["总而言之","顺便说一句","更好的是","更糟糕的是"],"answer_index":3,"explanation_cn":"to make matters worse = 更糟糕的是(引出更坏的情况)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"\"get the room in order\" 这个短语的意思是:","options":["把房间整理好","订购房间","命令房间","打扫院子"],"answer_index":0,"explanation_cn":"get the room in order = 把房间整理好、收拾整齐(in order = 井然有序)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"Why did the writer put his books on the floor?","options":["He had no books left","He was reading them all","The room was small, so he temporarily put them there","He wanted a carpet"],"answer_index":2,"passage":"We have just moved into a new house and I have been working hard all morning. I have been trying to get my new room in order. This has not been easy because I own over a thousand books. To make matters worse, the room is rather small, so I have temporarily put my books on the floor. At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room. A short while ago, my sister helped me to carry one of my old bookcases up the stairs. She went into my room and got a big surprise when she saw all those books on the floor. ''This is the prettiest carpet I have ever seen,'' she said. She gazed at it for some time then added, ''You don''t need bookcases at all. You can sit here in your spare time and read the carpet!''","explanation_cn":"课文说 the room is rather small, so I have temporarily put my books on the floor。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"What did the sister suggest?","options":["He should buy more bookcases","He doesn''t need bookcases — he can sit and ''read the carpet''","He should get a bigger room","He should sell his books"],"answer_index":1,"passage":"We have just moved into a new house and I have been working hard all morning. I have been trying to get my new room in order. This has not been easy because I own over a thousand books. To make matters worse, the room is rather small, so I have temporarily put my books on the floor. At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room. A short while ago, my sister helped me to carry one of my old bookcases up the stairs. She went into my room and got a big surprise when she saw all those books on the floor. ''This is the prettiest carpet I have ever seen,'' she said. She gazed at it for some time then added, ''You don''t need bookcases at all. You can sit here in your spare time and read the carpet!''","explanation_cn":"课文说妹妹打趣:You don''t need bookcases at all. You can sit here… and read the carpet!"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"What is the writer''s ''carpet'' really made of?","options":["His books, spread over the floor","Colored tiles","Wool","Old newspapers"],"answer_index":0,"audio":"We have just moved into a new house and I have been working hard all morning. I have been trying to get my new room in order. This has not been easy because I own over a thousand books. To make matters worse, the room is rather small, so I have temporarily put my books on the floor. At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room. A short while ago, my sister helped me to carry one of my old bookcases up the stairs. She went into my room and got a big surprise when she saw all those books on the floor. ''This is the prettiest carpet I have ever seen,'' she said. She gazed at it for some time then added, ''You don''t need bookcases at all. You can sit here in your spare time and read the carpet!''","explanation_cn":"课文里的\"地毯\"其实是铺满地板的书(they cover every inch of floor space)。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l52',10,NULL,'choice','{"stem":"How does the writer get in and out of the room?","options":["He crawls under them","There is a clear path","Through a window","He has to walk on the books"],"answer_index":3,"audio":"We have just moved into a new house and I have been working hard all morning. I have been trying to get my new room in order. This has not been easy because I own over a thousand books. To make matters worse, the room is rather small, so I have temporarily put my books on the floor. At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room. A short while ago, my sister helped me to carry one of my old bookcases up the stairs. She went into my room and got a big surprise when she saw all those books on the floor. ''This is the prettiest carpet I have ever seen,'' she said. She gazed at it for some time then added, ''You don''t need bookcases at all. You can sit here in your spare time and read the carpet!''","explanation_cn":"课文说 I actually have to walk on them to get in or out of the room。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
